"""Screenshot a wlroots compositor through zwlr_screencopy_manager_v1 (shm), for headless checks.

grim prefers ext-image-copy-capture, which the pixman renderer of a headless sway answers without
formats; the older wlr-screencopy works there. Usage: wlshot.py OUT.png [output-name]"""
import mmap
import os
import sys

# Python bindings generated by setup-chroot.sh (pywayland-scanner) from the protocol XML.
sys.path.insert(0, os.environ.get("WLSHOT_PROTOCOLS_DIR", "/opt/shot"))
from PIL import Image
from pywayland.client import Display
from protocols.wayland import WlOutput, WlShm
from protocols.wlr_screencopy_unstable_v1 import ZwlrScreencopyManagerV1

out_path = sys.argv[1]
want = sys.argv[2] if len(sys.argv) > 2 else None
display = Display()
display.connect()
registry = display.get_registry()
state = {"outputs": [], "shm": None, "mgr": None}


def on_global(reg, name, interface, version):
    if interface == "wl_output":
        o = reg.bind(name, WlOutput, min(version, 4))
        info = {"obj": o, "name": None}
        o.dispatcher["name"] = lambda _o, n: info.__setitem__("name", n)
        state["outputs"].append(info)
    elif interface == "wl_shm":
        state["shm"] = reg.bind(name, WlShm, 1)
    elif interface == "zwlr_screencopy_manager_v1":
        state["mgr"] = reg.bind(name, ZwlrScreencopyManagerV1, min(version, 3))


registry.dispatcher["global"] = on_global
display.roundtrip()
display.roundtrip()
if state["mgr"] is None:
    sys.exit("no zwlr_screencopy_manager_v1")
output = next((o for o in state["outputs"] if want is None or o["name"] == want), None)
if output is None:
    sys.exit("no such output")

frame = state["mgr"].capture_output(0, output["obj"])
fmt = {}
done = {"ok": None}


def on_buffer(_f, format_, width, height, stride):
    if "w" not in fmt:
        fmt.update(f=format_, w=width, h=height, s=stride)


frame.dispatcher["buffer"] = on_buffer
frame.dispatcher["buffer_done"] = lambda _f: done.__setitem__("bufdone", True)
frame.dispatcher["ready"] = lambda _f, *a: done.__setitem__("ok", True)
frame.dispatcher["failed"] = lambda _f: done.__setitem__("ok", False)
frame.dispatcher["flags"] = lambda _f, flags: fmt.__setitem__("flags", flags)
while "w" not in fmt or (not done.get("bufdone") and frame.version >= 3):
    display.dispatch(block=True)
size = fmt["s"] * fmt["h"]
fd = os.memfd_create("wlshot")
os.ftruncate(fd, size)
pool = state["shm"].create_pool(fd, size)
buf = pool.create_buffer(0, fmt["w"], fmt["h"], fmt["s"], fmt["f"])
frame.copy(buf)
while done["ok"] is None:
    display.dispatch(block=True)
if not done["ok"]:
    sys.exit("capture failed")
data = mmap.mmap(fd, size)
img = Image.frombuffer("RGBA", (fmt["w"], fmt["h"]), bytes(data), "raw", "BGRA", fmt["s"], 1)
if fmt.get("flags", 0) & 1:   # y_invert
    img = img.transpose(Image.FLIP_TOP_BOTTOM)
img.convert("RGB").save(out_path)
print(out_path, fmt["w"], fmt["h"], flush=True)
os._exit(0)   # pywayland crashes tearing down its proxies
